def topo_sort(graph):
    # Build reverse graph for incoming edges
    incoming_edges = {}
    all_nodes = set()

    # Collect all nodes and build incoming edges
    for node, prereqs in graph.items():
        all_nodes.add(node)
        for prereq in prereqs:
            all_nodes.add(prereq)
            if prereq not in incoming_edges:
                incoming_edges[prereq] = []
            incoming_edges[prereq].append(node)

    # Build in-degree count for each node
    in_degree = {node: 0 for node in all_nodes}
    for node in all_nodes:
        for prereq in graph.get(node, []):
            in_degree[node] += 1

    # Find nodes with no prerequisites (in-degree = 0)
    queue = []
    for node in all_nodes:
        if in_degree[node] == 0:
            queue.append(node)
    queue.sort()  # Sort lexicographically to ensure smallest first if multiple

    result = []
    while queue:
        # Pop smallest lexicographically from queue
        node = queue.pop(0)
        result.append(node)

        # Process neighbors (prerequisite nodes)
        for neighbor in graph.get(node, []):
            # Reduce in-degree of neighbors
            in_degree[neighbor] -= 1
            # If in-degree becomes 0, add to queue for processing
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Check for cycles (if result length doesn't match total nodes)
    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")

    return result
